import os
import torch

# =============================================================================
# GLOBAL CONFIGURATION FOR SFRP-NET (Idea 5)
# =============================================================================

# --- Reproducibility ---
SEED = 42

# --- File Paths ---
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"

# Metadata Files (Generated by previous steps)
TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

# Working Directory Structure
# All artifacts for this specific idea are isolated in idea_5
WORKING_DIR = "./working/idea_5"
CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
PREDICTION_DIR = os.path.join(WORKING_DIR, "predictions")
CACHE_DIR = os.path.join(WORKING_DIR, "cache")

# Final Submission Output
SUBMISSION_FILE = "./submission.csv"

# --- Data Parameters ---
Z_DIM = 65  # Depth of the input volume (number of slices)
PATCH_SIZE = (512, 512)  # Spatial dimensions of input crops (Height, Width)
NUM_WORKERS = 4  # Number of subprocesses for data loading

# --- Model Architecture: SFRP-Net ---
# Split-Frequency Resolution-Preserving Network settings
MODEL_CHANNELS = 32  # Base channel width (reduced to fit BS=32 in memory)
STREAM_B_DILATIONS = [1, 2, 4, 8]  # Dilations for the Context Stream (Stream B)

# --- Training Hyperparameters ---
BATCH_SIZE = 32  # Strict constraint to maintain iteration budget
EPOCHS = 15  # Training duration
LEARNING_RATE = 1e-3  # Initial learning rate for Adam
POS_WEIGHT = 2.0  # BCE Loss positive class weight to handle imbalance

# --- Hardware Settings ---
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"


# --- Utility Functions ---
def setup_directories():
    """
    Ensures that all necessary working directories exist.
    This should be called at the start of training or inference scripts.
    """
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(PREDICTION_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)
    print(f"Directories initialized at {WORKING_DIR}")
